-- Meteorology academy: lessons 5-9. Idempotent; all records stay unpublished.
with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch2 as (
 insert into public.academy_chapters(course_id,title,description,sort_order,published)
 select id,'تحليل الأنظمة الجوية وتطورها','تطور المنخفضات والأخاديد والنتوءات والدوامية.',2,false from c
 on conflict(course_id,title) do update set description=excluded.description returning id,course_id
),
u2 as (
 insert into public.academy_units(chapter_id,title,description,sort_order,published)
 select id,'المنخفضات والأخاديد والدوامية','تحليل الأنظمة الجوية في خرائط الطبقات العليا والسطح.',1,false from ch2
 on conflict(chapter_id,title) do update set description=excluded.description returning id,chapter_id
),
ch3 as (
 insert into public.academy_chapters(course_id,title,description,sort_order,published)
 select id,'الرطوبة والديناميكا الحرارية الجوية','بخار الماء والتشبع والعمليات الحرارية وعدم الاستقرار.',3,false from c
 on conflict(course_id,title) do update set description=excluded.description returning id,course_id
),
u3 as (
 insert into public.academy_units(chapter_id,title,description,sort_order,published)
 select id,'الرطوبة والتشبع والتكاثف','مقاييس الرطوبة ودرجة الندى وتكوّن السحب.',1,false from ch3
 on conflict(chapter_id,title) do update set description=excluded.description returning id,chapter_id
),
u4 as (
 insert into public.academy_units(chapter_id,title,description,sort_order,published)
 select id,'الحرارة والاستقرار والحمل','العمليات الأديباتية ومؤشرات طاقة الحمل.',2,false from ch3
 on conflict(chapter_id,title) do update set description=excluded.description returning id,chapter_id
),
rows as (
 select c.id cid,ch2.id chid,u2.id uid,v.* from c cross join ch2 cross join u2 cross join (values
 ('development-of-synoptic-lows','تطور المنخفضات الجوية','نشأة المنخفضات الجبهية ومراحل نموها والعوامل المؤثرة في تعمقها.',
 $lesson5$
{"blocks":[
{"type":"heading","text":"مفهوم تطور المنخفض الجوي"},
{"type":"text","text":"المنخفض نظام يكون ضغطه أقل من المناطق المحيطة عند مستوى التحليل. تطوره يعني تغير شدته وشكله وموقعه وبنيته مع الزمن. تختلف آليات نشأة المنخفضات؛ فالمنخفضات الجبهية في العروض الوسطى تختلف عن المنخفضات الحرارية والمدارية."},
{"type":"heading","text":"المنخفضات الجبهية"},
{"type":"text","text":"ترتبط كثير من المنخفضات الجبهية بتباين أفقي في درجات الحرارة وبالقص الرأسي للرياح. قد تنمو اضطرابات على طول الجبهة، ويتطور معها دوران إعصاري وتوزيع منظم لمناطق التقارب والصعود."},
{"type":"heading","text":"مراحل التطور المفاهيمية"},
{"type":"list","items":["مرحلة الاضطراب أو الموجة: يظهر انحناء أو اضطراب على منطقة التباين الحراري.","مرحلة النمو: يزداد تنظيم الدوران والجبهات ومناطق الصعود.","مرحلة النضج: يبلغ النظام تنظيماً وشدة ملحوظين، وقد تتكون جبهة انسداد في بعض الحالات.","مرحلة الاضمحلال: يضعف التباين الحراري أو الدعم الديناميكي ويبدأ النظام بالامتلاء." ]},
{"type":"callout","text":"هذا تسلسل تعليمي شائع للمنخفضات الجبهية، وليس قانوناً زمنياً ثابتاً؛ فالأنظمة الحقيقية قد تختلف عنه."},
{"type":"heading","text":"العوامل المساعدة على التعمق"},
{"type":"list","items":["تباين حراري أفقي وقص رأسي ملائمان.","تباعد في طبقات الجو العليا يساعد على إعادة توزيع الكتلة.","تقارب قرب السطح وصعود واسع النطاق في مواضع مناسبة.","تفاعل الأخاديد العلوية والتيار النفاث مع النظام السطحي."]},
{"type":"heading","text":"التحليل على الخرائط"},
{"type":"text","text":"لا يكفي فحص قيمة الضغط السطحي وحدها. قارن خرائط الضغط عند سطح البحر بخرائط الارتفاع الجهدي عند 500 hPa وخرائط الرياح عند 300 أو 250 hPa، وتابع تغير مركز المنخفض والجبهات والهطول بين أوقات التحليل."},
{"type":"example","title":"مثال تحليلي","text":"إذا أظهرت خرائط متتابعة انخفاض الضغط في مركز نظام جبهوي مع اقتراب أخدود علوي، فقد تكون هناك إشارة إلى تعمق المنخفض.","solution":"أكد ذلك بمراجعة الرياح والتباعد العلوي والحرارة والرصد السطحي؛ فالضغط وحده لا يحدد سبب التغير."},
{"type":"heading","text":"خلاصة الدرس"},
{"type":"text","text":"تطور المنخفض نتيجة تفاعل حراري وديناميكي متعدد المستويات. التحليل الجيد يربط السطح بالطبقات العليا ويتابع التغير الزمني."}
]}
$lesson5$,50,25,'["شرح المراحل المفاهيمية لتطور المنخفض الجبهي","تحديد العوامل الحرارية والديناميكية المؤثرة في تعمقه","ربط خرائط السطح بخرائط الطبقات العليا"]'::jsonb
 )) as v(slug,title,summary,content,ord,mins,objectives)
 union all
 select c.id,ch2.id,u2.id,v.* from c cross join ch2 cross join u2 cross join (values
 ('upper-troughs-ridges-and-vorticity','الأخاديد والنتوءات والدوامية','قراءة الموجات الجوية في خرائط الارتفاع الجهدي وفهم الدوامية.',
 $lesson6$
{"blocks":[
{"type":"heading","text":"الأخدود والنتوء"},
{"type":"text","text":"الأخدود (Trough) امتداد ممدود نسبياً لمنطقة ارتفاعات جهدية منخفضة، والنتوء (Ridge) امتداد لمنطقة ارتفاعات أعلى. يظهران بوضوح على خرائط 500 hPa ويساعدان على وصف الموجات واسعة النطاق."},
{"type":"heading","text":"قراءة خطوط الارتفاع"},
{"type":"text","text":"خطوط الارتفاع الجهدي تصل بين نقاط لها الارتفاع نفسه عند مستوى ضغط محدد. انحناؤها يصف شكل الموجة، وتقاربها يرتبط غالباً بتدرج أقوى وسرعة رياح جيوستروفية أكبر إذا بقيت العوامل الأخرى متقاربة."},
{"type":"list","items":["الأخدود: انحناء نحو قيم ارتفاع أقل، ويرتبط كثيراً بهواء أبرد نسبياً في الطبقات الوسطى، لكن ذلك ليس شرطاً مطلقاً.","النتوء: انحناء نحو قيم ارتفاع أعلى، ويرتبط كثيراً بامتداد هواء أدفأ أو بهبوط نسبي في بعض الحالات.","الموجات القصيرة: اضطرابات أصغر تتحرك ضمن النمط واسع النطاق."]},
{"type":"heading","text":"الدوامية"},
{"type":"text","text":"الدوامية (Vorticity) مقياس للدوران المحلي للمائع. نستخدم في التحليل غالباً المركبة الرأسية للدوامية النسبية، التي تصف الدوران حول المحور الرأسي. في نصف الكرة الشمالي تشير الدوامية الموجبة عادة إلى دوران عكس عقارب الساعة وفق الاصطلاح الشائع."},
{"type":"formula","text":"ζ = ∂v/∂x − ∂u/∂y"},
{"type":"text","text":"يرمز u إلى مركبة الرياح الشرقية وv إلى مركبتها الشمالية، وζ إلى المركبة الرأسية للدوامية النسبية في إحداثيات محلية."},
{"type":"heading","text":"تغير الدوامية"},
{"type":"text","text":"تتغير الدوامية بفعل النقل مع الرياح والتمدد أو الانكماش والقص الأفقي والاحتكاك. لذلك لا تعني قيمة الدوامية المرتفعة وحدها حدوث هطول؛ بل يجب تحليل النقل والتباعد والرطوبة والحركة الرأسية."},
{"type":"callout","text":"في نصف الكرة الجنوبي تنعكس دلالة اتجاه الدوران المرتبطة بإشارة الدوامية وفق الاصطلاح نفسه. انتبه دائماً إلى نصف الكرة وتعريف المتغير."},
{"type":"heading","text":"الاستخدام التنبؤي"},
{"type":"text","text":"تابع الأخاديد والنتوءات والدوامية عند 500 hPa وقارنها بالرياح والتباعد في الطبقات العليا وبالرطوبة والحركة الرأسية. يساعد الدمج على تحديد مناطق الدعم الديناميكي المحتملة للصعود."},
{"type":"example","title":"مثال قراءة خريطة","text":"قد يزيد احتمال عدم الاستقرار أو الهطول مع اقتراب أخدود علوي إذا توافرت الرطوبة والرفع المناسب.","solution":"لا تعتمد على الأخدود وحده؛ افحص ملف الرطوبة والاستقرار وموقع المنطقة بالنسبة إلى حركة الموجة."},
{"type":"heading","text":"خلاصة الدرس"},
{"type":"text","text":"الأخاديد والنتوءات تصف شكل الموجات الجوية، والدوامية تصف الدوران. دمجها مع الرطوبة والحركة الرأسية يحسن التحليل."}
]}
$lesson6$,60,30,'["تمييز الأخاديد والنتوءات على خرائط 500 hPa","تعريف الدوامية النسبية وشرح إشارتها","ربط الموجات العلوية بعناصر التحليل الأخرى"]'::jsonb
 )) as v(slug,title,summary,content,ord,mins,objectives)
 union all
 select c.id,ch3.id,u3.id,v.* from c cross join ch3 cross join u3 cross join (values
 ('humidity-saturation-and-condensation','الرطوبة والتشبع والتكاثف','مقاييس بخار الماء ودرجة الندى والتشبع وتكوّن السحب.',
 $lesson7$
{"blocks":[
{"type":"heading","text":"بخار الماء في الغلاف الجوي"},
{"type":"text","text":"بخار الماء مكوّن متغير في الهواء، وهو أساسي في تكوّن السحب والهطول وانتقال الطاقة الكامنة. تتغير كميته بفعل التبخر والنتح والنقل والتكاثف والهطول."},
{"type":"heading","text":"مقاييس الرطوبة"},
{"type":"list","items":["ضغط بخار الماء: الضغط الجزئي الذي يسهم به بخار الماء ضمن الهواء.","الرطوبة النسبية: نسبة ضغط بخار الماء الفعلي إلى ضغط الإشباع عند درجة الحرارة نفسها مضروبة في 100%.","نسبة الخلط: كتلة بخار الماء مقارنة بكتلة الهواء الجاف.","الرطوبة النوعية: كتلة بخار الماء مقسومة على الكتلة الكلية للهواء الرطب.","درجة الندى: درجة الحرارة التي يصبح عندها الهواء مشبعاً عند تبريد مناسب."]},
{"type":"formula","text":"RH = (e / eₛ) × 100%"},
{"type":"text","text":"يرمز e إلى ضغط بخار الماء الفعلي، ويرمز eₛ إلى ضغط الإشباع عند درجة الحرارة نفسها."},
{"type":"heading","text":"التشبع"},
{"type":"text","text":"يكون الهواء مشبعاً عندما يصل ضغط بخار الماء إلى ضغط الإشباع عند درجة حرارته. يعتمد ضغط الإشباع بقوة على الحرارة؛ فالهواء الأدفأ يستطيع دعم ضغط بخار أعلى قبل الوصول إلى التشبع."},
{"type":"heading","text":"التكاثف وتكوّن السحب"},
{"type":"text","text":"عندما يبرد الهواء الرطب إلى درجة الندى أو يضاف إليه بخار ماء حتى يبلغ التشبع، يمكن أن يبدأ التكاثف على نوى مناسبة. تتكون قطرات سحابية صغيرة وقد تنمو لاحقاً بعمليات ميكروفيزيائية مختلفة."},
{"type":"callout","text":"الرطوبة النسبية 100% لا تعني تلقائياً هطول المطر؛ فالهطول يحتاج إلى نمو الجسيمات السحابية بما يكفي لتسقط وتصل إلى السطح."},
{"type":"heading","text":"آليات رفع الهواء"},
{"type":"list","items":["الرفع التضاريسي فوق المرتفعات.","الرفع الجبهي عند التقاء كتل هوائية مختلفة.","التقارب السطحي الذي يدعم الصعود في بعض الأنظمة.","الحمل الحراري الناتج عن التسخين وعدم الاستقرار."]},
{"type":"example","title":"مثال مبسط","text":"إذا كانت حرارة الهواء 20°C ودرجة الندى 18°C فالفارق صغير نسبياً ويشير إلى هواء قريب من التشبع قرب السطح.","solution":"هذا مؤشر وصفي وليس ضماناً لتكوّن السحب؛ افحص أيضاً ملف الحرارة والرطوبة مع الارتفاع وآلية الرفع."},
{"type":"heading","text":"خلاصة الدرس"},
{"type":"text","text":"فهم مقاييس الرطوبة ودرجة الندى والتشبع يساعد على تقدير قابلية الهواء لتكوين السحب، ويجب دمجه مع الرفع والاستقرار والعمليات الميكروفيزيائية."}
]}
$lesson7$,70,25,'["التمييز بين الرطوبة النسبية ونسبة الخلط والرطوبة النوعية","شرح التشبع ودرجة الندى","تفسير دور الرفع ونوى التكاثف في تكوّن السحب"]'::jsonb
 )) as v(slug,title,summary,content,ord,mins,objectives)
 union all
 select c.id,ch3.id,u4.id,v.* from c cross join ch3 cross join u4 cross join (values
 ('atmospheric-thermodynamics-and-adiabatic-processes','الديناميكا الحرارية الجوية والعمليات الأديباتية','الطرد الهوائي ومعدلات التناقص الحراري والتغير الأديباتي والاستقرار.',
 $lesson8$
{"blocks":[
{"type":"heading","text":"الديناميكا الحرارية الجوية"},
{"type":"text","text":"تدرس الديناميكا الحرارية الجوية العلاقة بين الحرارة والضغط والحجم والرطوبة والطاقة في الهواء. تساعد هذه المفاهيم على فهم السحب والحمل الحراري والاستقرار وتطور العواصف."},
{"type":"heading","text":"الطرد الهوائي والبيئة"},
{"type":"text","text":"نستخدم نموذج الطرد الهوائي (Air Parcel) لتتبع تغير كتلة صغيرة من الهواء أثناء صعودها أو هبوطها. نقارن درجة حرارتها بدرجة حرارة البيئة المحيطة لتقدير ميلها إلى الاستمرار في الحركة أو مقاومتها."},
{"type":"heading","text":"معدل التناقص الحراري البيئي"},
{"type":"text","text":"معدل التناقص الحراري البيئي هو مقدار انخفاض درجة حرارة البيئة مع زيادة الارتفاع. يتغير من حالة إلى أخرى، وقد ينخفض أو ينعكس في طبقات الانقلاب الحراري."},
{"type":"heading","text":"العملية الأديباتية"},
{"type":"text","text":"في العملية الأديباتية المثالية لا يحدث تبادل حراري مع الوسط المحيط. عند صعود الطرد يتمدد مع انخفاض الضغط فيبرد، وعند هبوطه ينضغط فيسخن. قبل التشبع يكون معدل التبريد الجاف قريباً من 9.8°C لكل كيلومتر في الغلاف الجوي القياسي تقريباً."},
{"type":"formula","text":"Γd ≈ 9.8 °C/km"},
{"type":"text","text":"بعد التشبع يصبح معدل التبريد الأديباتي الرطب متغيراً، ويتأثر بدرجة الحرارة والضغط ومحتوى الرطوبة، ويكون غالباً أقل من المعدل الجاف بسبب إطلاق الحرارة الكامنة أثناء التكاثف."},
{"type":"heading","text":"الاستقرار بصورة أولية"},
{"type":"list","items":["مستقر: يميل الطرد المزاح رأسياً إلى العودة نحو مستوى اتزانه أو مقاومة الإزاحة.","غير مستقر: يميل الطرد إلى مواصلة الابتعاد عن موضعه بعد الإزاحة.","محايد: لا توجد قوة طفو صافية تعيده أو تدفعه بعيداً في التقريب المستخدم."]},
{"type":"callout","text":"الحكم الدقيق على الاستقرار يتطلب مقارنة مسار الطرد بملف حرارة البيئة مع مراعاة الرطوبة ومستويات التكاثف والحمل."},
{"type":"heading","text":"خلاصة الدرس"},
{"type":"text","text":"تغير درجة حرارة الطرد أثناء صعوده أو هبوطه عنصر أساسي في تفسير السحب والحمل. التمييز بين المعدل البيئي والجاف والرطب ضروري."}
]}
$lesson8$,80,30,'["شرح مفهوم الطرد الهوائي والعملية الأديباتية","التمييز بين معدل التناقص الحراري البيئي والجاف والرطب","تفسير العلاقة بين ملف الحرارة والاستقرار"]'::jsonb
 ),
 ('convective-available-potential-energy-and-inhibition','طاقة الحمل المتاحة وطاقة منع الحمل (CAPE وCIN)','المعنى الفيزيائي لمؤشري CAPE وCIN وقراءتهما ضمن ملف السبر الجوي.',
 $lesson9$
{"blocks":[
{"type":"heading","text":"عدم الاستقرار الحملي"},
{"type":"text","text":"يحدث الحمل الحراري عندما تكتسب كتل الهواء طفوياً موجباً وتستطيع الصعود. يعتمد ذلك على مقارنة حرارة الطرد الافتراضي بدرجة حرارة البيئة على امتداد الارتفاع، إضافة إلى الرطوبة وآلية بدء الرفع."},
{"type":"heading","text":"طاقة الحمل المتاحة CAPE"},
{"type":"text","text":"CAPE هي طاقة الطفو الموجبة المتاحة للطرد الهوائي بين مستوى بدء الحمل الحر (LFC) ومستوى التوازن الأعلى (EL)، وفق تعريف مسار الطرد المستخدم. تقاس عادة بالجول لكل كيلوغرام."},
{"type":"formula","text":"CAPE = ∫ B dz"},
{"type":"text","text":"يمثل B تسارع الطفو، ويجري التكامل على طبقة الطفو الموجب وفق تعريف المنتج أو طريقة حساب مسار الطرد."},
{"type":"heading","text":"طاقة منع الحمل CIN"},
{"type":"text","text":"CIN تمثل مقدار الطاقة المرتبطة بالطفو السالب التي يجب التغلب عليها حتى يصل الطرد إلى مستوى بدء الحمل الحر (LFC). قد تعمل كغطاء يحد من الحمل، لكنها قد تؤخر بدءه إلى أن تتوفر آلية رفع أو تسخين مناسبة."},
{"type":"formula","text":"CIN = ∫ B dz (في طبقة الطفو السالب؛ تعرض غالباً كقيمة سالبة)"},
{"type":"heading","text":"قراءة المؤشرين معاً"},
{"type":"list","items":["CAPE مرتفعة تعني إمكانية طاقة طفو أكبر إذا بدأ الحمل، ولا تضمن وحدها حدوث عاصفة.","CIN قوية قد تمنع بدء الحمل رغم وجود CAPE ملحوظة.","CAPE ضعيفة لا تعني انعدام كل أشكال الهطول أو العواصف؛ فهناك آليات رفع وأنظمة غير حملية.","افحص الرطوبة وLCL وLFC وEL ومصدر الطرد والقص الرأسي وتوقيت التسخين أو مرور الجبهة."]},
{"type":"heading","text":"لماذا لا تكفي قيمة واحدة؟"},
{"type":"text","text":"تختلف قيم CAPE باختلاف نوع الطرد المستخدم، مثل طرد السطح أو متوسط الطبقة أو أكثر طرد غير مستقر. كما تختلف خوارزميات النماذج والمنتجات، لذلك يجب قراءة تعريف المؤشر في مصدر البيانات."},
{"type":"example","title":"مثال تفسيري","text":"قد تعرض خريطة CAPE قيمة موجبة مرتفعة مع وجود CIN ملحوظة. هذا يعني أن البيئة قد تملك طاقة حمل إذا تمكن الطرد من تجاوز طبقة الكبح.","solution":"افحص وجود تقارب أو جبهة أو تضاريس أو تسخين كافٍ لبدء الرفع، ثم قيّم القص والرطوبة وملف السبر. لا تستنتج حدوث عاصفة من CAPE وحدها."},
{"type":"callout","text":"CAPE وCIN مؤشرات تشخيصية وليستا تنبؤاً مستقلاً بحدوث عاصفة أو شدتها. يجب دمجهما مع الرصد والتحليل الديناميكي."},
{"type":"heading","text":"خلاصة الدرس"},
{"type":"text","text":"CAPE تصف طاقة الطفو الموجب، وCIN تصف كبح الطفو قبل بدء الحمل. تفسيرهما يتطلب فهم مسار الطرد وملف الحرارة والرطوبة والرفع والقص الرأسي."}
]}
$lesson9$,90,35,'["تعريف CAPE وCIN ووحداتهما ومعناهما الفيزيائي","شرح دور LFC وEL في مسار الطرد","تقييم حدود المؤشرين ودمجهما مع الرصد والقص والرفع"]'::jsonb
 )) as v(slug,title,summary,content,ord,mins,objectives)
)
insert into public.academy_lessons
(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select cid,chid,uid,slug,title,summary,content::jsonb,false,ord,'beginner',mins,objectives,
 case when ord<70 then 'تحليل الأنظمة الجوية وتطورها' else 'الرطوبة والديناميكا الحرارية الجوية' end,
 case when ord<70 then 'المنخفضات والأخاديد والدوامية'
      when ord=70 then 'الرطوبة والتشبع والتكاثف' else 'الحرارة والاستقرار والحمل' end
from rows
on conflict(course_id,slug) do update set
 chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,
 summary=excluded.summary,content=excluded.content,published=false,
 sort_order=excluded.sort_order,level=excluded.level,
 estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,
 chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;
